//! The menu bar icon: a monochrome template of the agent symbol, one image per state
//! (generated by `apps/desktop/scripts/icons.ts` in CI). macOS tints template images
//! for light and dark menu bars by itself.

use tauri::image::Image;
use tauri::tray::{MouseButton, MouseButtonState, TrayIconBuilder, TrayIconEvent};
use tauri::AppHandle;

const TRAY_ID: &str = "main";

const IDLE: &[u8] = include_bytes!("../icons/tray/idle.png");
const WORKING: &[u8] = include_bytes!("../icons/tray/working.png");
const PAUSED: &[u8] = include_bytes!("../icons/tray/paused.png");
const OFFLINE: &[u8] = include_bytes!("../icons/tray/offline.png");
const UPDATE: &[u8] = include_bytes!("../icons/tray/update.png");
/// An agent is in its browser: a ring in the corner.
const BROWSING: &[u8] = include_bytes!("../icons/tray/browsing.png");
/// An agent needs a person in its browser: a filled dot in the corner.
const NEEDS: &[u8] = include_bytes!("../icons/tray/needs.png");

fn bytes_for(state: &str) -> Option<&'static [u8]> {
    match state {
        "idle" => Some(IDLE),
        "working" => Some(WORKING),
        "paused" => Some(PAUSED),
        "offline" => Some(OFFLINE),
        "update" => Some(UPDATE),
        "browsing" => Some(BROWSING),
        "needs" => Some(NEEDS),
        _ => None,
    }
}

pub fn create(app: &AppHandle) -> tauri::Result<()> {
    TrayIconBuilder::with_id(TRAY_ID)
        .icon(Image::from_bytes(IDLE)?)
        .icon_as_template(true)
        .tooltip("agentes")
        .on_tray_icon_event(|tray, event| {
            // The positioner needs every tray event to know where the icon is.
            tauri_plugin_positioner::on_tray_event(tray.app_handle(), &event);
            if let TrayIconEvent::Click {
                button: MouseButton::Left | MouseButton::Right,
                button_state: MouseButtonState::Up,
                ..
            } = event
            {
                crate::toggle_popover(tray.app_handle());
            }
        })
        .build(app)?;
    Ok(())
}

pub fn set_state(app: &AppHandle, state: &str) -> Result<(), String> {
    let bytes = bytes_for(state).ok_or_else(|| format!("unknown tray state: {state}"))?;
    let tray = app.tray_by_id(TRAY_ID).ok_or("no tray icon")?;
    let image = Image::from_bytes(bytes).map_err(|e| e.to_string())?;
    tray.set_icon(Some(image)).map_err(|e| e.to_string())?;
    tray.set_icon_as_template(true).map_err(|e| e.to_string())?;
    Ok(())
}
